\label{hd:draw-intro}
Let $(M^3,g_0)$ be a closed hyperbolic three-manifold.
\begin{itemize}
\item There are smooth metrics $g$ arbitrarily close to $g_0$ in the
 tensor $C^0$ topology such that $\operatorname{Sc}_g\geq-6$ and $h(g)>2$.
\item For every $A>0$, there is a smooth metric $g$ such that
 $\operatorname{Sc}_g\geq-6$ and $h(g)>A$.
\end{itemize}

\label{q:KSX-local-entropy}
Let $(M^3,g_0)$ be a closed hyperbolic three-manifold. Does there exist
a $C^\infty$ neighborhood $\mathcal U$ of $g_0$ in the space of smooth
Riemannian metrics on $M$ such that
\begin{equation*}
 g\in\mathcal U,\qquad \operatorname{Sc}_g\geq-6
 \quad\Longrightarrow\quad h(g)\leq2?
\end{equation*}

\label{hd:main}
For every $n\geq3$, the constrained Hessian at $g_0$ is diagonal in an
$L^2$-orthogonal TT eigenbasis of $\Delta$. If $0\ne S\in\mathcal T_{\mathrm{TT}}$ and $\Delta S=\lambda S$,
then $\lambda\geq n$ and
\begin{equation}\label{hd:main-mode}
 \mathcal H(S,S)=\frac{(\lambda-2)(n-1)}{8}
 \bigl(\kappa_n(\lambda)-\frac{n+2}{n-1}\bigr)
 \|S^\vee\|_{L^2(SM,m_0)}^2.
\end{equation}
The function $\kappa_n$ is strictly decreasing on
$[n,\infty)$ and tends to zero.

\begin{itemize}
\item For $n=3$, $\mathcal H$ is negative definite on $\mathcal T_{\mathrm{TT}}$.
\item For every $n\geq4$, there is exactly one $\lambda_*(n)>n$ satisfying
\begin{equation*}
 \kappa_n(\lambda_*(n))=\frac{n+2}{n-1}.
\end{equation*}
The positive space of $\mathcal H$ is the sum of the TT eigenspaces with
$n\leq\lambda<\lambda_*(n)$; its kernel is the eigenspace at
$\lambda_*(n)$; and its negative space is the sum of those above it.
The positive space and kernel are finite-dimensional, and the negative
space is infinite-dimensional.
\end{itemize}

\label{hd:bochner}
For $S\in\mathcal T_{\mathrm{TT}}$, put $C_{ijk}=\nabla_iS_{jk}-\nabla_jS_{ik}$. Then
\begin{equation}\label{hd:codazzi-energy}
 \frac12\|C\|_{L^2}^2=\langle (\nabla^*\nabla-n)S,S\rangle_{L^2}.
\end{equation}
In particular $\nabla^*\nabla\geq n$ on $\mathcal T_{\mathrm{TT}}$, with equality exactly for
trace-free Codazzi tensors, that is, tensors satisfying $C=0$.

\label{thm:constrained-hessian}
Let $g_s\in\mathcal M_{-n(n-1)}$ be a $C^2$ curve through $g_0$ with
$S=\dot g_0\in\mathcal T_{\mathrm{TT}}$.  Then
\begin{equation}\label{eq:main-hessian}
 \boxed{\begin{aligned}
 \mathcal H(S,S)
 :=\left.\frac{d^2}{ds^2}\right|_0h(g_s)
 &=\frac{n-1}{8}\operatorname{Cov}_0\bigl((PS)^\vee,S^\vee\bigr)
 -\frac{1}{4nV_0}\langle PS,S\rangle_{L^2(M)},\\
 &\hspace{35mm} P=\nabla^*\nabla-2.
 \end{aligned}}
\end{equation}
The right-hand side depends only on $S$ and not on the acceleration of the
chosen constrained curve.  By Lemma~\ref{lem:integrability}, every
$S\in\mathcal T_{\mathrm{TT}}$ occurs in such a curve.

\label{thm:negative-directions}
Assume $n\geq3$.  On $\mathcal T_{\mathrm{TT}}$, the quadratic form $\mathcal H$ in
\eqref{eq:main-hessian} is represented by a self-adjoint operator with
negative elliptic principal symbol of order two and domain $H^2\cap\overline{\mathcal T_{\mathrm{TT}}}^{L^2}$.  In particular:
\begin{enumerate}
 \item $\mathcal H$ is not positive definite;
 \item it has infinitely many negative directions;
 \item its positive spectral subspace is finite-dimensional.
\end{enumerate}
Equivalently, $\mathcal H$ is strictly negative on the orthogonal
complement of a sufficiently large finite-dimensional subspace of $\mathcal T_{\mathrm{TT}}$.

\label{hd:polar-laplace}
For $r>0$, the radial component $U$ satisfies
\begin{equation}\label{hd:polar-equation}
 \partial_r^2U+(n+3)\coth r\,\partial_rU
 -\frac{\Delta_\sigma U}{\sinh^2r}
 +(\lambda+2n\coth^2r)U=0.
\end{equation}

\label{pro:correlation}
For $S\in E_\lambda$ and every smooth trace-free symmetric two-tensor
$A$, the correlation satisfies
\begin{equation}\label{eq:correlation-factor}
 \int_{SM}A^\vee(S^\vee\circ\phi_t)\,dm_0
 =\varphi_{n,\lambda}(t)\int_{SM}A^\vee S^\vee\,dm_0
 \qquad(t\in\mathbb R),
\end{equation}
where $\varphi_{n,\lambda}\colon\mathbb R\to\mathbb R$ is the unique
smooth even solution of
\begin{equation}\label{hd:correlation-ode}
 \varphi''+(n+3)\coth r\,\varphi'+(\lambda+2n)\varphi=0,
 \qquad \varphi(0)=1,\quad \varphi'(0)=0.
\end{equation}
The differential equation holds for $r>0$.

\label{thm:covariance-multiplier}
Let $0\ne S\in\mathcal T_{\mathrm{TT}}$ satisfy $\Delta S=\lambda S$, and let $A$ be any
smooth trace-free symmetric two-tensor. Then
\begin{equation}\label{hd:covariance-final}
 \operatorname{Cov}_0(A^\vee,S^\vee)=\kappa_n(\lambda)
       \int_{SM}A^\vee S^\vee\,dm_0,
 \qquad
 \kappa_n(\lambda)=\frac{J(a+\mu)J(a-\mu)}{J(n+3)}.
\end{equation}
In particular, this proves Theorem~\ref{thm:intro-covariance}.

\label{thm:negative-definite-3d}\label{cor:coercive-3d}
Let
\[
 \eta=5-\frac{15\pi^2}{32}>0,\qquad c_0=\frac{\eta}{240V_0}.
\]
Then
\begin{equation}\label{eq:negative-definite-3d}
 \mathcal H(S,S)\leq-c_0\|S\|_{H^1}^2\qquad(S\in\mathcal T_{\mathrm{TT}}).
\end{equation}

\label{lem:entropy-remainder}
After shrinking the coordinate neighborhood in
Lemma~\ref{lem:constraint-coordinates}, the metrics $G(S)$ have
negative sectional curvature, and the function $F(S)=h(G(S))$ is $C^3$ near zero in $\mathcal T_{\mathrm{TT}}^8$.
There is a constant $C$ such that
\begin{equation}\label{eq:uniform-remainder}
 \left|F(S)-2-\tfrac12\mathcal H(S,S)\right|
 \leq C\|S\|_{H^1}^2\|S\|_{H^{22}}
\end{equation}
for smooth $S$ sufficiently small in $H^{22}$.

\label{hd:codazzi-sign}
For a nonzero trace-free Codazzi tensor $S$,
\begin{equation*}
 \mathcal H(S,S)=\frac{(n-1)(n-2)}{8}
       \bigl(K_n-\frac{n+2}{n-1}\bigr)\|S^\vee\|^2_{L^2(SM,m_0)}.
\end{equation*}
This is negative for $n=3$ and positive for every $n\geq4$.
For $n=4$,
\[
 \mathcal H(S,S)=\frac1{10}\|S^\vee\|^2_{L^2(SM,m_0)}
        =\frac{1}{120V_0}\|S\|^2_{L^2(M)}.
\]

\label{hd:flat-bundle}
On a closed hyperbolic manifold $M=\Gamma\backslash\mathbb H^n$,
\[
 \{\hbox{trace-free Codazzi symmetric two-tensors}\}
 \simeq H^1(\Gamma;\mathbb R^{n,1}).
\]
